namespace Claims;

public sealed class ClaimAdjudicator
{
    public ClaimDecision Evaluate(Claim? claim, ICoverageRegister coverageRegister, IRiskScreen riskScreen)
    {
        if (claim is null)
            return new ClaimDecision("rejected", 0m, ["missing-claim"]);

        var reasons = new List<string>();
        AddClaimValidationReasons(claim, reasons);

        var coverage = coverageRegister.Find(claim.PolicyNumber);
        AddCoverageReasons(coverage, reasons);
        AddDocumentationReasons(claim, reasons);
        AddRiskReason(riskScreen.Score(claim), reasons);

        if (reasons.Any(IsRejectionReason))
            return new ClaimDecision("rejected", 0m, reasons);
        if (reasons.Any(IsReviewReason))
            return new ClaimDecision("review", 0m, reasons);

        var payable = CalculatePayable(claim, coverage!);
        if (payable == 0m)
            return new ClaimDecision("declined-no-benefit", 0m, [.. reasons, "no-benefit-remaining"]);

        return new ClaimDecision("approved", decimal.Round(payable, 2), reasons);
    }

    private static void AddClaimValidationReasons(Claim claim, List<string> reasons)
    {
        if (string.IsNullOrWhiteSpace(claim.Reference))
            reasons.Add("missing-reference");
        if (string.IsNullOrWhiteSpace(claim.PolicyNumber))
            reasons.Add("missing-policy");
        if (claim.ClaimedAmount <= 0m)
            reasons.Add("invalid-amount");
        if (claim.DaysAfterIncident < 0)
            reasons.Add("invalid-incident-age");
        if (claim.DaysAfterIncident > 90)
            reasons.Add("late-notification");
    }

    private static void AddCoverageReasons(Coverage? coverage, List<string> reasons)
    {
        if (coverage is null)
            reasons.Add("unknown-policy");
        else if (!coverage.Active)
            reasons.Add("inactive-policy");
        else if (!coverage.CoversCategory)
            reasons.Add("excluded-category");
    }

    private static void AddDocumentationReasons(Claim claim, List<string> reasons)
    {
        if (!claim.DocumentsComplete)
            reasons.Add("documents-incomplete");
        if (claim.Category == "theft" && !claim.PoliceReportPresent)
            reasons.Add("police-report-required");
    }

    private static void AddRiskReason(int riskScore, List<string> reasons)
    {
        if (riskScore >= 80)
            reasons.Add("manual-risk-review");
        else if (riskScore < 0)
            reasons.Add("invalid-risk-score");
    }

    private static bool IsRejectionReason(string reason) =>
        reason is "missing-reference" or "missing-policy" or "invalid-amount" or
            "invalid-incident-age" or "unknown-policy" or "inactive-policy" or
            "excluded-category" or "police-report-required";

    private static bool IsReviewReason(string reason) =>
        reason is "documents-incomplete" or "late-notification" or "manual-risk-review";

    private static decimal CalculatePayable(Claim claim, Coverage coverage)
    {
        var payable = Math.Max(0m, claim.ClaimedAmount - coverage.Deductible);
        return Math.Min(payable, Math.Max(0m, coverage.Limit - claim.PriorPaidAmount));
    }
}
